  1	// Shared fixtures for the POST /groups/:id/import suites (not a test file itself).
  2	import assert from 'node:assert/strict'
  3	import { readFileSync, statSync } from 'node:fs'
  4	import { startApp, tempDataFile } from './helpers.mjs'
  5	
  6	export const trip = { id: 'trip', name: 'Ski trip', members: ['Ann', 'Ben', 'Cara'] }
  7	export const flat = { id: 'flat', name: 'Flat', members: ['Ann', 'Ben', 'Cara'] }
  8	export const everyone = trip.members
  9	
 10	// A valid expense or payment entry, with some fields replaced.
 11	export const expense = (over = {}) => ({ type: 'expense', description: 'Hotel', payer: 'Ann', amount: 90, ...over })
 12	export const payment = (over = {}) => ({ type: 'payment', from: 'Ben', to: 'Ann', amount: 30, ...over })
 13	
 14	// The same expense as POST /groups/:id/expenses takes it (no type).
 15	export const asPost = ({ type, ...fields }) => fields
 16	
 17	// Runs fn({ call, file, restart, importInto }) with the "trip" group created on a fresh data file.
 18	export async function withTrip(fn) {
 19	  const data = tempDataFile()
 20	  let app = await startApp(data.file)
 21	  try {
 22	    assert.equal((await app.call('POST', '/groups', trip)).status, 201)
 23	    const call = (...args) => app.call(...args)
 24	    const restart = async () => {
 25	      await app.stop()
 26	      app = await startApp(data.file)
 27	    }
 28	    const importInto = (body, group = 'trip') => call('POST', `/groups/${group}/import`, body)
 29	    await fn({ call, file: data.file, restart, importInto })
 30	  } finally {
 31	    await app.stop()
 32	    data.cleanup()
 33	  }
 34	}
