 42	// Everything the API shows about a group's ledger.
 43	export async function ledger(call, group = 'trip') {
 44	  const [expenses, payments, balances] = await Promise.all(
 45	    ['expenses', 'payments', 'balances'].map(part => call('GET', `/groups/${group}/${part}`)),
 46	  )
 47	  return { ...expenses.body, ...payments.body, ...balances.body }
 48	}
 49	
 50	// Asserts that a request left the data file and the ledger exactly as they were.
 51	export async function assertNothingSaved({ call, file }, before) {
 52	  assert.deepEqual(snapshot(file), before.file)
 53	  assert.deepEqual(await ledger(call), before.ledger)
 54	}
 55	
 56	export async function capture({ call, file }) {
 57	  return { file: snapshot(file), ledger: await ledger(call) }
 58	}
 59	// POST /groups/:id/import: the checks on the request as a whole (413, not an object, 404, 400), in order.
 60	import { test } from 'node:test'
 61	import assert from 'node:assert/strict'
 62	import { assertNothingSaved, capture, expense, payment, withTrip } from './import-fixtures.mjs'
 63	
 64	const ENTRIES_ERROR = { error: 'entries must be an array of 1 to 50 items' }
 65	const DRY_RUN_ERROR = { error: 'dry_run must be true or false' }
 66	const SKIP_ERROR = { error: 'skip_recorded must be true or false' }
 67	const MAX_BODY_BYTES = 10 * 1024
 68	
 69	// Sends body (an object, or raw JSON text) and asserts the exact status and reply, and that nothing was saved.
 70	async function assertRefused(ctx, body, status, reply, group = 'trip') {
 71	  const before = await capture(ctx)
 72	  const r = await ctx.importInto(body, group)
 73	  assert.equal(r.status, status, typeof body === 'string' ? body : JSON.stringify(body))
 74	  assert.deepEqual(r.body, reply)
 75	  await assertNothingSaved(ctx, before)
 76	}
 77	
 78	// Raw JSON text of exactly `bytes` bytes for a valid one-payment import, padded with spaces inside the object.
 79	function paddedBody(bytes) {
 80	  const text = JSON.stringify({ entries: [payment()] })
 81	  return `${text.slice(0, -1)}${' '.repeat(bytes - Buffer.byteLength(text))}}`
 82	}
 83	
 84	test('import: an unknown group is 404 not found, before any check of the body fields', () => withTrip(async ctx => {
 85	  const notFound = { error: 'not found' }
 86	  await assertRefused(ctx, { entries: [expense()] }, 404, notFound, 'nope')
 87	  await assertRefused(ctx, { bogus: 1, entries: 'x', dry_run: null }, 404, notFound, 'nope')
 88	  await assertRefused(ctx, { entries: [null] }, 404, notFound, 'nope')
 89	}))
 90	
 91	test('import: a body that is not a JSON object is 400, even for an unknown group', () => withTrip(async ctx => {
 92	  for (const text of ['[]', '[{"entries": []}]', 'null', '"entries"', '7', 'true']) {
 93	    await assertRefused(ctx, text, 400, { error: 'body must be a JSON object' })
 94	    await assertRefused(ctx, text, 400, { error: 'body must be a JSON object' }, 'nope')
 95	  }
 96	  await assertRefused(ctx, '{"entries": [', 400, { error: 'invalid JSON' })
 97	}))
 98	
 99	test('import: a body over 10 KB is 413; exactly 10 KB is accepted', () => withTrip(async ctx => {
100	  await assertRefused(ctx, paddedBody(MAX_BODY_BYTES + 1), 413, { error: 'body too large' })
101	  await assertRefused(ctx, paddedBody(MAX_BODY_BYTES + 1), 413, { error: 'body too large' }, 'nope')
102	  const r = await ctx.importInto(paddedBody(MAX_BODY_BYTES))
103	  assert.equal(r.status, 201)
104	  assert.deepEqual(r.body.payments, [{ id: 1, from: 'Ben', to: 'Ann', amount: 30 }])
105	}))
106	
107	test('import: an unknown body field is 400 naming the first one in Object.keys order', () => withTrip(async ctx => {
108	  const entries = [expense()]
109	  await assertRefused(ctx, { entries, extra: 1 }, 400, { error: 'unknown field extra' })
110	  await assertRefused(ctx, { zeta: 1, entries, alpha: 2 }, 400, { error: 'unknown field zeta' })
111	  // Integer-like keys come first in Object.keys, whatever their place in the text.
112	  await assertRefused(ctx, '{"entries": [], "b": 1, "2": 1}', 400, { error: 'unknown field 2' })
113	  await assertRefused(ctx, `{"__proto__": {}, "entries": ${JSON.stringify(entries)}}`, 400, { error: 'unknown field __proto__' })
114	  for (const name of ['Entries', 'dryRun', 'dry_run ', 'skip-recorded', 'type', '']) {
115	    await assertRefused(ctx, { entries, [name]: false }, 400, { error: `unknown field ${name}` })
116	  }
117	}))
118	
119	test('import: an unknown field is reported before bad entries and bad flags', () => withTrip(async ctx => {
120	  await assertRefused(ctx, { dry_run: 'x', entries: 'x', extra: null }, 400, { error: 'unknown field extra' })
121	  await assertRefused(ctx, { extra: undefined, entries: [] }, 400, ENTRIES_ERROR) // undefined is dropped by JSON
122	}))
123	
124	test('import: entries must be an array of 1 to 50 items', () => withTrip(async ctx => {
125	  const fiftyOne = Array.from({ length: 51 }, () => payment())
126	  for (const entries of [undefined, null, {}, { 0: payment() }, 'entries', 1, true, [], fiftyOne]) {
127	    await assertRefused(ctx, { entries }, 400, ENTRIES_ERROR)
128	  }
129	  await assertRefused(ctx, {}, 400, ENTRIES_ERROR)
130	}))
131	
132	test('import: 50 entries are accepted, each with its own id', () => withTrip(async ({ importInto }) => {
133	  const r = await importInto({ entries: Array.from({ length: 50 }, () => payment()) })
134	  assert.equal(r.status, 201)
135	  assert.deepEqual(r.body.payments.map(p => p.id), Array.from({ length: 50 }, (_, i) => i + 1))
136	}))
137	
138	test('import: a bad entries list is reported before bad flags', () => withTrip(async ctx => {
139	  await assertRefused(ctx, { dry_run: 'x', skip_recorded: 'x', entries: [] }, 400, ENTRIES_ERROR)
140	  await assertRefused(ctx, { skip_recorded: null, dry_run: null, entries: [expense()] }, 400, DRY_RUN_ERROR)
141	}))
142	
143	test('import: dry_run and skip_recorded must be booleans when given, null included', () => withTrip(async ctx => {
144	  const entries = [expense()]
145	  for (const value of [null, 'true', 'false', 0, 1, '', [], {}, [true]]) {
146	    await assertRefused(ctx, { entries, dry_run: value }, 400, DRY_RUN_ERROR)
147	    await assertRefused(ctx, { entries, skip_recorded: value }, 400, SKIP_ERROR)
148	    await assertRefused(ctx, { entries, dry_run: true, skip_recorded: value }, 400, SKIP_ERROR)
149	  }
150	}))
151	
152	test('import: flags given as false behave as left out and the import is saved', () => withTrip(async ({ call, importInto }) => {
153	  const r = await importInto({ entries: [expense()], dry_run: false, skip_recorded: false })
154	  assert.equal(r.status, 201)
155	  assert.deepEqual((await call('GET', '/groups/trip/expenses')).body, { expenses: r.body.expenses })
156	}))
157	
158	test('import: entries with bad fields and an unknown group are still 404 first', () => withTrip(async ctx => {
159	  await assertRefused(ctx, { entries: [expense({ amount: 0 })] }, 404, { error: 'not found' }, 'Trip')
160	}))
  1	import { mkdtempSync, rmSync } from 'node:fs'
  2	import { tmpdir } from 'node:os'
  3	import { join } from 'node:path'
  4	import { createApp } from '../server.mjs'
